CREATE OR REPLACE FUNCTION public.fx_convert(p_amount numeric, p_from text, p_to text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb; r_from numeric; r_to numeric;
begin
  if p_amount is null then return null; end if;
  if coalesce(p_from, 'GBP') = coalesce(p_to, 'GBP') then return p_amount; end if;
  select value into v from public.app_settings where key = 'fx_rates';
  -- Rates are quoted against the base (GBP): EUR 1.17 means 1 GBP = 1.17 EUR.
  r_from := case when coalesce(p_from, 'GBP') = coalesce(v ->> 'base', 'GBP') then 1
                 else (v ->> p_from)::numeric end;
  r_to   := case when coalesce(p_to, 'GBP') = coalesce(v ->> 'base', 'GBP') then 1
                 else (v ->> p_to)::numeric end;
  if r_from is null or r_to is null or r_from = 0 then return p_amount; end if;
  return round(p_amount * r_to / r_from, 2);
end $function$;
